def signedHemisphereVertexMatrix (n : ℕ) (ε : ℝ) (i : Fin (n + 2)) :
    Matrix (Fin (n + 2)) (Fin (n + 2)) ℝ :=
  Matrix.of (Fin.cons (Fin.cons ε 0) (fun row => Fin.cons 0 (signedFacetVertexMatrix n i row)))

